import{CONFIG}from '/js/modules/config.min.js';import{UI}from '/js/modules/ui.min.js';import{Renderer}from '/js/modules/renderer.min.js';class PortfolioApp{constructor(){this.data=window.mainPortfolio||[];this.gallery=window.galleryData||[];this.ui=new UI();this.renderer=new Renderer(this.data,this.gallery);this.init();}init(){try{this.renderer.renderAll();this.ui.initAll();let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>this.renderer.renderAll(),200);});const yearEl=document.getElementById(CONFIG.DOM.footerYear);if(yearEl)yearEl.textContent=new Date().getFullYear();}catch(error){console.error('ERROR CRÍTICO EN MAIN:',error);document.body.classList.remove('loading');const pl=document.getElementById('preloader');if(pl)pl.style.display='none';}}}document.addEventListener('DOMContentLoaded',()=>new PortfolioApp());